    public List<String> buildArray(int[] target, int n) {
        List<String> result = new ArrayList<>();
        int current = 1;

        for (int value : target) {
            while (current < value) {
                result.add("Push");
                result.add("Pop");
                current++;
            }
            result.add("Push");
            current++;
        }

        return result;
    }
