typedef struct {
    char* s;
    int pos;
    int len;
} Tok;

static void skipWS(Tok* t) {
    while (t->pos < t->len &&
           (t->s[t->pos] == ' ' || t->s[t->pos] == ',' ||
            t->s[t->pos] == '\t' || t->s[t->pos] == '\n' ||
            t->s[t->pos] == '\r')) {
        t->pos++;
    }
}

static char* nextToken(Tok* t) {
    skipWS(t);
    if (t->pos >= t->len) return NULL;

    int start = t->pos;
    if (t->s[t->pos] == '[') {
        int depth = 0;
        while (t->pos < t->len) {
            char c = t->s[t->pos++];
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) break;
            }
        }
    } else {
        while (t->pos < t->len &&
               t->s[t->pos] != ',' && t->s[t->pos] != ']' &&
               t->s[t->pos] != '[') {
            t->pos++;
        }
    }

    int token_len = t->pos - start;
    char* token = (char*)malloc(token_len + 1);
    if (!token) return NULL;
    memcpy(token, t->s + start, token_len);
    token[token_len] = '\0';

    int idx = token_len - 1;
    while (idx >= 0 && (token[idx] == ' ' || token[idx] == '\t' ||
                         token[idx] == '\n' || token[idx] == '\r')) {
        token[idx--] = '\0';
    }
    return token;
}

static int parse_int(Tok* t) {
    char* tok = nextToken(t);
    if (!tok) return 0;
    int val = atoi(tok);
    free(tok);
    return val;
}

static int* parse_int_array(Tok* t, int* out_size) {
    char* tok = nextToken(t);
    if (!tok || strcmp(tok, "[]") == 0) {
        if (tok) free(tok);
        *out_size = 0;
        return NULL;
    }

    int len = (int)strlen(tok);
    char* inner = (char*)malloc((size_t)len - 1);
    if (!inner) {
        free(tok);
        *out_size = 0;
        return NULL;
    }
    memcpy(inner, tok + 1, (size_t)len - 2);
    inner[len - 2] = '\0';
    free(tok);

    int size = 1;
    for (int i = 0; inner[i]; i++) {
        if (inner[i] == ',') size++;
    }

    int* arr = (int*)malloc((size_t)size * sizeof(int));
    if (!arr) {
        free(inner);
        *out_size = 0;
        return NULL;
    }

    Tok t2 = { inner, 0, (int)strlen(inner) };
    for (int i = 0; i < size; i++) arr[i] = parse_int(&t2);

    free(inner);
    *out_size = size;
    return arr;
}

static char* dup_cstr(const char* s) {
    size_t len = strlen(s);
    char* out = (char*)malloc(len + 1);
    if (!out) return NULL;
    memcpy(out, s, len + 1);
    return out;
}

