    char** result = (char**)malloc((size_t)maxOps * sizeof(char*));
    if (!result) {
        *returnSize = 0;
        return NULL;
    }

    int count = 0;
    int targetIndex = 0;

    for (int x = 1; x <= n && targetIndex < targetSize; x++) {
        result[count++] = dup_cstr("Push");

        if (x == target[targetIndex]) {
            targetIndex++;
        } else {
            result[count++] = dup_cstr("Pop");
        }
    }

    *returnSize = count;
    return result;
}

